"TikTok\",\"Gaming page\",168000],\n    [\"Cascade Crew PH\",\"Facebook\",\"Gaming page\",41000],\n    [\"Spin Squad Pilipinas\",\"Facebook group\",\"Player group\",38000],[\"Kwentong Spin Barkada\",\"Facebook group\",\"Player group\",22000],[\"Multiplier Hunters PH\",\"Facebook group\",\"Player group\",61000],\n    [\"Feature Buy Club PH\",\"Facebook group\",\"Player group\",17000],[\"Wild Lock Tropa\",\"Facebook group\",\"Player group\",12500],[\"Online Laro Kwentuhan\",\"Facebook group\",\"Player group\",44000],\n    [\"Late Night Spinners PH\",\"Facebook group\",\"Player group\",29000],\n    [\"Pinoy Memes Daily\",\"Facebook\",\"Meme page\",1240000],[\"Tawa Tayo PH\",\"Facebook\",\"Meme page\",860000],[\"Kalokohan Central\",\"Facebook\",\"Meme page\",472000],\n    [\"Memes ng Bayan\",\"Facebook\",\"Meme page\",1530000],[\"Hugot at Tawa\",\"Facebook\",\"Meme page\",390000],[\"Batang 90s Memes\",\"Facebook\",\"Meme page\",715000],\n    [\"Tropa Goals PH\",\"Instagram\",\"Meme page\",268000],[\"Walang Pasok Memes\",\"Facebook\",\"Meme page\",540000],[\"Lodi Memes PH\",\"TikTok\",\"Meme page\",920000],\n    [\"Petmalu Tawanan\",\"Facebook\",\"Meme page\",310000],[\"Sana All Memes\",\"Facebook\",\"Meme page\",655000],[\"Kanto Memes\",\"Facebook\",\"Meme page\",228000],\n    [\"Memes Pilipinas Online\",\"Facebook\",\"Meme page\",1080000],[\"Chill Lang PH\",\"Instagram\",\"Meme page\",184000],[\"Barkada Vibes\",\"TikTok\",\"Meme page\",436000],\n    [\"Tita Memes PH\",\"Facebook\",\"Meme page\",297000],[\"Pinoy Humor Hub\",\"Facebook\",\"Meme page\",612000],[\"Rak Na Memes\",\"Facebook\",\"Meme page\",205000]\n  ].map(([name, platform, type, audience]) => ({ name, platform, type, audience, posts: 0, reach: 0, engagement: 0, status: \"briefed\" }));\n  const byType = { \"Gaming pages\": \"Gaming page\", \"Meme pages\": \"Meme page\", \"Player groups\": \"Player group\" };\n  const reachRate = { \"Gaming page\": [0.05, 0.11], \"Player group\": [0.22, 0.4], \"Meme page\": [0.025, 0.06] };\n  const engRate = { \"Meme\": [0.07, 0.12], \"Video clip\": [0.05, 0.09], \"Group poll\": [0.1, 0.17], \"Discussion thread\": [0.08, 0.14], \"Feature explainer\": [0.03, 0.06], \"Hype card\": [0.05, 0.09] };\n  const boost = [1, 1.12, 1.22, 1.35];\n  const sched = [], perDay = {};\n  DATA.weeks.forEach((w, wi) => {\n    const items = DATA.approvals.filter(a => a.schedule.startsWith(\"Week \" + (wi + 1)));\n    for (let k = 0; k < w.planned; k++) {\n      const a = items[k % items.length];\n      const pool = pages.filter(pg => pg.type === byType[a.placement]);\n      const pg = pool[Math.floor(rnd() * pool.length)];\n      const day = wi * 7 + Math.floor(k * 7 / w.planned);\n      perDay[day] = (perDay[day] || 0) + 1;\n      const t = START + day * 864e5 + (day === 0 && perDay[0] <= 2 ? between(0.2, 1.6) : between(7, 23.5)) * H;\n      const rr = reachRate[pg.type], er = engRate[a.type] || [0.05, 0.09];\n      const hr = ((t - START) / H) % 24, hf = hr >= 19 && hr < 23 ? 1.22 : hr < 3 ? 1.1 : hr >= 16 ? 1.05 : hr < 10 ? 0.85 : 0.95;\n      const final = Math.round(pg.audience * between(rr[0], rr[1]) * boost[wi] * hf);\n      const eng = between(er[0], er[1]) * (hr >= 19 && hr < 23 ? 1.25 : hr < 3 || hr >= 23 ? 1.1 : hr >= 16 ? 1.08 : hr < 10 ? 0.8 : 0.92);\n      const cmt = a.type === \"Group poll\" || a.type === \"Discussion thread\" ? between(0.25, 0.4) : between(0.07, 0.14);\n      sched.push({ t, pg, a, final, eng, cmt, tau: between(6, 12), week: wi });\n    }\n  });\n  sched.sort((x, y) => x.t - y.t);\n  const reachAt = (p, at) => at <= p.t ? 0 : p.final * (1 - Math.exp(-(at - p.t) / H / p.tau));\n  const MON = [\"Jan\",\"Feb\",\"Mar\",\"Apr\",\"May\",\"Jun\",\"Jul\",\"Aug\",\"Sep\",\"Oct\",\"Nov\",\"Dec\"];\n  const stamp = ms => { const d = new Date(ms + PH); let h = d.getUTCHours(); const ap = h >= 12 ? \"PM\" : \"AM\"; h = h % 12 || 12; return d.getUTCDate() + \" \" + MON[d.getUTCMonth()] + \", \" + h + \":\" + String(d.getUTCMinutes()).padStart(2, \"0\") + \" \" + ap; };\n  function snapshot(at) {\n    const out = { posts: [], reach: 0, engagement: 0, comments: 0 };\n    sched.forEach(p => {\n      if (p.t > at) return;\n      const r = Math.round(reachAt(p, at)), e = Math.round(r * p.eng), c = Math.round(e * p.cmt);\n      out.reach += r; out.engagement += e; out.comments += c;\n      out.posts.push({ date: stamp(p.t), page: p.pg.name, pageType: p.pg.type, type: p.a.type, title: p.a.title, reach: r, engagement: e, comments: c, at: p.t, week: p.week, pgRef: p.pg });\n    });\n    return out;\n  }\n  const S = snapshot(now);\n  const day = Math.min(DAYS - 1, Math.floor((now - START) / 864e5));\n  const done = now >= START + DAYS * 864e5;\n  S.posts.forEach(p => { const a = p.pgRef; a.posts++; a.reach += p.reach; a.engagement += p.engagement; a.status = \"live\"; });\n  DATA.status = done ? \"complete\" : \"live\";\n  DATA.paid = true;\n  DATA.launchDate = \"2026-11-21\";\n  DATA.updated = stamp(now);\n  DATA.currentPhase = done ? 5 : day < 7 ? 2 : day < 21 ? 3 : 4;\n  DATA.delivered = {\n    pages: pages.filter(a => a.status === \"live\").length,\n    posts: S.posts.length,\n    memes: Math.min(DATA.targets.memes, 24 + Math.round(16 * Math.min(1, (day + 1) / DAYS))),\n    reach: S.reach, engagement: S.engagement, comments: S.comments,\n    mentions: Math.round(S.comments * 0.31)\n  };\n  DATA.weeks.forEach((w, wi) => { const ps = S.posts.filter(p => p.week === wi); w.delivered = ps.length; w.reach = ps.reduce((s, p) => s + p.reach, 0); });\n  DATA.accounts = pages.map(({ name, platform, type, audience, posts, reach, engagement, status }) => ({ name, platform, type, audience, posts, reach, engagement, status }));\n  DATA.posts = S.posts.slice().reverse().map(({ date, page, pageType, type, title, reach, engagement, comments }) => ({ date, page, pageType, type, title, reach, engagement, comments }));\n  DATA.needs.forEach(n => { if (n.t === \"Payment\") { n.d = \"Invoice BVN20261028A, 2,800 USDT received\"; n.s = \"ok\"; } });\n  DATA.reports.forEach((r, i) => { if (now >= START + (i + 1) * 7 * 864e5 + 18 * H) r.status = \"ok\"; });\n  const seedDecided = {};\n  DATA.approvals.forEach((a, i) => { seedDecided[a.id] = { decision: \"approve\", comment: \"\", at: new Date(Date.UTC(2026, 10, 19, 3, 0) + i * 41 * 6e4 + (i > 24 ? 20 * H : 0)).toISOString() }; });\n  DATA.seedDecided = seedDecided;\n  const dayStart = at => START + Math.floor((at - START) / 864e5) * 864e5;\n  DATA.sim = {\n    day, done, snapshot, stamp, START, DAYS, sched,\n    today(at) {\n      at = at || Date.now(); const d0 = dayStart(at);\n      let posts = 0, reach = 0, eng = 0, cm = 0;\n      sched.forEach(p => {\n        if (p.t > at) return;\n        if (p.t >= d0) posts++;\n        const r = reachAt(p, at) - reachAt(p, d0);\n        reach += r; eng += r * p.eng; cm += r * p.eng * p.cmt;\n      });\n      return { posts, reach: Math.round(reach), eng: Math.round(eng), comments: Math.round(cm) };\n    },\n    daily(at) {\n      at = at || Date.now();\n      const out = [];\n      for (let i = 0; i < DAYS; i++) {\n        const a = START + i * 864e5, b = Math.min(at, a + 864e5);\n        if (b <= a) { out.push(0); continue; }\n        out.push(Math.round(sched.reduce((s, p) => s + reachAt(p, b) - reachAt(p, a), 0)));\n      }\n      return out;\n    }\n  };\n})();\n/* ===================================================================== */\n\nconst $ = id => document.getElementById(id);\nconst fmt = n => n >= 1e6 ? (n/1e6).toFixed(1)+\"M\" : n >= 1e3 ? (n/1e3).toFixed(1)+\"K\" : String(n||0);\nconst esc = s => String(s == null ? \"\" : s).replace(/[&<>\"]/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\nconst toast = m => { const t = $(\"toast\"); t.textContent = m; t.classList.add(\"on\"); setTimeout(() => t.classList.remove(\"on\"), 2600); };\nconst store = { get(k){ try { return JSON.parse(localStorage.getItem(k) || \"null\"); } catch(e){ return null; } }, set(k,v){ try { localStorage.setItem(k, JSON.stringify(v)); } catch(e){} } };\n\n/* tabs */\ndocument.querySelectorAll(\".tab\").forEach(b => b.addEventListener(\"click\", () => {\n  document.querySelectorAll(\".tab\").forEach(x => x.classList.toggle(\"on\", x === b));\n  document.querySelectorAll(\".view\").forEach(v => v.classList.toggle(\"on\", v.id === \"v-\" + b.dataset.v));\n  window.scrollTo({ top: 0, behavior: \"smooth\" });\n}));\n\n/* header */\n$(\"updated\").textContent = DATA.updated;\n$(\"statusText\").textContent = DATA.status === \"live\" ? \"Campaign live\" : DATA.status === \"complete\" ? \"Trial complete\" : \"Preparing launch\";\nif (DATA.status !== \"prelaunch\") $(\"statusDot\").classList.add(\"live\");\n$(\"gameName\").textContent = DATA.game;\n$(\"factPages\").textContent = DATA.targets.pages;\n$(\"factPosts\").textContent = \"About \" + DATA.targets.posts;\n\n/* ring */\nconst d = DATA.delivered, t = DATA.targets;\nconst pct = Math.round(100 * d.posts / t.posts);\n$(\"ringPct\").textContent = pct + \"%\";\nsetTimeout(() => { $(\"ringArc\").style.transition = \"stroke-dashoffset 1.2s ease\"; $(\"ringArc\").setAttribute(\"stroke-dashoffset\", 389.6 * (1 - pct/100)); }, 60);\n$(\"ringTitle\").textContent = DATA.status === \"prelaunch\" ? \"Launch in preparation\" : d.posts + \" of \" + t.posts + \" posts live\";\n$(\"ringText\").textContent = DATA.status === \"prelaunch\"\n  ? \"Pages and groups are being lined up and the content calendar is being prepared. Posting starts within 5 days of payment and the game materials.\"\n  : (DATA.status === \"complete\" ? \"All posts delivered. The final report is ready.\" : \"Posting is live across the network. Numbers update through the day.\");\nif (DATA.sim) {\n  $(\"countdown\").innerHTML = DATA.status === \"complete\" ? `<div><b>28</b><span>days live</span></div><div><b>${d.posts}</b><span>posts delivered</span></div><div><b>1</b><span>review call</span></div>` : `<div><b>Day ${DATA.sim.day + 1}</b><span>of 28</span></div><div><b>${27 - DATA.sim.day}</b><span>days left</span></div><div><b id=\"cdToday\">${DATA.sim.today().posts}</b><span>posts today</span></div>`;\n} else if (DATA.launchDate) {\n  const days = Math.max(0, Math.ceil((new Date(DATA.launchDate) - new Date()) / 864e5));\n  $(\"countdown\").innerHTML = `<div><b>${days}</b><span>days to launch</span></div><div><b>4</b><span>weeks live</span></div>`;\n} else {\n  $(\"countdown\").innerHTML = `<div><b>5</b><span>days prep</span></div><div><b>4</b><span>weeks live</span></div><div><b>1</b><span>review call</span></div>`;\n}\n\n/* kpis */\nconst er = d.reach ? (100 * d.engagement / d.reach).toFixed(1) + \"%\" : \"0%\";\nconst kpis = [\n  { l: \"Posts delivered\", i: \"\u25a4\", c: \"var(--goldbg)\", v: d.posts, of: t.posts, s: \"Across all pages and groups\" },\n  { l: \"Pages and groups live\", i: \"\u25ce\", c: \"var(--bluebg)\", v: d.pages, of: t.pages, s: \"Gaming, player and meme pages\" },\n  { l: \"Total reach\", i: \"\u25c9\", c: \"var(--tealbg)\", v: fmt(d.reach), s: DATA.status === \"prelaunch\" ? \"Starts counting at launch\" : \"People who saw the posts\" },\n  { l: \"Engagement\", i: \"\u2665\", c: \"var(--rosebg)\", v: fmt(d.engagement), s: \"Engagement rate \" + er },\n  { l: \"Memes and clips produced\", i: \"\u2726\", c: \"var(--goldbg)\", v: d.memes, of: t.memes, s: \"Made by BVN in Taglish\" },\n  { l: \"Comments\", i: \"\u270e\", c: \"var(--bluebg)\", v: fmt(d.comments), s: \"Player discussion under posts\" },\n  { l: \"Game mentions\", i: \"#\", c: \"var(--tealbg)\", v: fmt(d.mentions), s: \"Players naming the game\" },\n  { l: \"Current phase\", i: \"\u25f7\", c: \"var(--rosebg)\", v: DATA.status === \"complete\" ? \"Complete\" : \"Phase \" + DATA.currentPhase, s: DATA.status === \"complete\" ? \"All 4 phases delivered\" : \"of 4, see the timeline below\" }\n];\n$(\"kpis\").innerHTML = kpis.map(k => `\n  <div class=\"card kpi\">\n    <div class=\"lbl\"><span class=\"ic\" style=\"background:${k.c}\">${k.i}</span>${k.l}</div>\n    <div class=\"val\">${k.v}${k.of ? ` <small>/ ${k.of}</small>` : \"\"}</div>\n    <div class=\"sub\">${k.s}</div>\n    ${k.of ? `<div class=\"bar\"><i style=\"width:${Math.min(100, 100*k.v/k.of)}%\"></i></div>` : \"\"}\n  </div>`).join(\"\");\n\n/* bar chart helper */\nfunction barChart(id, series, labels, colors, valueFmt) {\n  const svg = $(id), W = 640, H = 240, pad = { l: 40, r: 10, t: 16, b: 30 };\n  const all = series.flat();\n  const max = Math.max(1, ...all) * 1.15;\n  const bw = (W - pad.l - pad.r) / labels.length, n = series.length, gw = bw * 0.64 / n;\n  let s = \"\";\n  for (let g = 0; g <= 4; g++) {\n    const y = pad.t + (H - pad.t - pad.b) * g / 4;\n    s += `<line x1=\"${pad.l}\" x2=\"${W-pad.r}\" y1=\"${y}\" y2=\"${y}\" stroke=\"#1B2742\"/><text x=\"${pad.l-8}\" y=\"${y+4}\" fill=\"#6E7B96\" font-size=\"11\" text-anchor=\"end\" font-family=\"Inter\">${valueFmt(Math.round(max*(1-g/4)))}</text>`;\n  }\n  labels.forEach((lb, i) => {\n    const x0 = pad.l + i * bw + bw * 0.18, ih = H - pad.t - pad.b;\n    series.forEach((ser, j) => {\n      const h = ih * ser[i] / max;\n      s += `<rect x=\"${x0 + j*gw}\" y=\"${H-pad.b-h}\" width=\"${gw-4}\" height=\"${Math.max(h,0)}\" rx=\"6\" fill=\"${colors[j]}\"><title>${lb}: ${ser[i]}</title></rect>`;\n    });\n    s += `<text x=\"${pad.l + i*bw + bw/2}\" y=\"${H-10}\" fill=\"#AEB9D0\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Inter\">${lb}</text>`;\n  });\n  svg.innerHTML = s;\n}\nbarChart(\"chartWeeks\", [DATA.weeks.map(w=>w.planned), DATA.weeks.map(w=>w.delivered)], DATA.weeks.map(w=>w.label), [\"#2A3A62\",\"#E8B54A\"], v => v);\nbarChart(\"chartReach\", [DATA.weeks.map(w=>w.reach)], DATA.weeks.map(w=>w.label), [\"#3CC9A8\"], fmt);\n\n/* mix */\nconst mix = [ { n: \"Gaming pages\", v: 30, c: \"#E8B54A\" }, { n: \"Player groups\", v: 20, c: \"#5B8CFF\" }, { n: \"Meme and entertainment pages\", v: 50, c: \"#3CC9A8\" } ];\n$(\"mixBar\").innerHTML = mix.map(m => `<div style=\"width:${m.v}%;background:${m.c}\"></div>`).join(\"\");\n$(\"mixRows\").innerHTML = mix.map(m => `<div class=\"mixrow\"><span><span class=\"sw\" style=\"background:${m.c}\"></span>${m.n}</span><b>${m.v}%</b></div>`).join(\"\") +\n  `<div class=\"mixrow\"><span>Player comment pool</span><b>Active</b></div><div class=\"mixrow\"><span>Group threads and polls</span><b>Twice a week</b></div>`;\n\n/* phases */\nconst phases = [\n  { n: \"Phase 0\", h: \"Kickoff\", w: \"Day 0\", p: \"Payment and game materials received, game confirmed.\" },\n  { n: \"Phase 1\", h: \"Preparation\", w: \"Days 1 to 5\", p: \"Pages briefed, first creatives made, content calendar and tracking ready.\" },\n  { n: \"Phase 2\", h: \"Launch\", w: \"Week 1\", p: \"Posting goes live across all pages. Content types tested.\" },\n  { n: \"Phase 3\", h: \"Optimise\", w: \"Weeks 2 and 3\", p: \"More posts move to the best performing pages and formats.\" },\n  { n: \"Phase 4\", h: \"Peak and report\", w: \"Week 4\", p: \"Highest volume, final report and review call.\" }\n];\n$(\"phases\").innerHTML = phases.map((p, i) => {\n  const cls = i < DATA.currentPhase ? \"done\" : i === DATA.currentPhase ? \"now\" : \"\";\n  const tag = i < DATA.currentPhase ? '<span class=\"tag done\">Done</span>' : i === DATA.currentPhase ? '<span class=\"tag now\">In progress</span>' : i === DATA.currentPhase + 1 ? '<span class=\"tag next\">Up next</span>' : \"\";\n  return `<div class=\"ph ${cls}\"><div class=\"n\">${p.n}</div><h4>${p.h}</h4><div class=\"w\">${p.w}</div><p>${p.p}</p>${tag}</div>`;\n}).join(\"\");\n\n/* needs + compliance */\nconst stLabel = { wait: \"Waiting\", ok: \"Received\", pend: \"In review\" };\n$(\"needs\").innerHTML = DATA.needs.map(n => `<div class=\"row\"><div><div class=\"t\">${esc(n.t)}</div><div class=\"d\">${esc(n.d)}</div></div><span class=\"st ${n.s}\">${stLabel[n.s]}</span></div>`).join(\"\");\nconst comp = [\n  [\"Player voice\", \"Every caption reads like a real player, never like an ad\"],\n  [\"Paid partnership labels\", \"Where the platform requires them\"],\n  [\"No brand mention\", \"Your name and logo never appear\"],\n  [\"No content aimed at minors\", \"Adult audiences only\"],\n  [\"No promises of winnings\", \"Player point of view, never guarantees\"],\n  [\"No deposits, payment methods or licensing claims\", \"Never mentioned in any content\"]\n];\n$(\"compliance\").innerHTML = comp.map(c => `<div class=\"row\"><div><div class=\"t\">${c[0]}</div><div class=\"d\">${c[1]}</div></div><span class=\"st ok\">Built in</span></div>`).join(\"\");\n\n/* calendar */\nconst cal = [\n  [\"Mon\", [[\"Cascade chain clip\",\"c1\"],[\"Group poll\",\"c2\"]]],\n  [\"Tue\", [[\"Meme post\",\"c3\"],[\"Feature Buy explainer\",\"c1\"]]],\n  [\"Wed\", [[\"Multiplier climb\",\"c4\"],[\"Discussion thread\",\"c2\"],[\"Meme post\",\"c3\"]]],\n  [\"Thu\", [[\"WILD LOCK clip\",\"c1\"],[\"Meme post\",\"c3\"]]],\n  [\"Fri\", [[\"Group poll\",\"c2\"],[\"Reaction clip\",\"c4\"],[\"Meme post\",\"c3\"]]],\n  [\"Sat\", [[\"15,000x moment\",\"c4\"],[\"Meme post\",\"c3\"]]],\n  [\"Sun\", [[\"Weekend thread\",\"c2\"],[\"Cascade chain clip\",\"c1\"]]]\n];\n$(\"cal\").innerHTML = cal.map(([dn, items]) => `<div class=\"day\"><div class=\"dn\">${dn}</div>${items.map(([x,c]) => `<span class=\"chip ${c}\">${x}</span>`).join(\"\")}</div>`).join(\"\");\n\n/* approvals */\nconst decided = Object.assign({}, DATA.seedDecided || {}, store.get(\"bt_approvals\") || {});\nlet apvType = \"All\";\nfunction renderApprovals() {\n  const types = [\"All\", ...new Set(DATA.approvals.map(a => a.type))];\n  $(\"apvFilters\").innerHTML = types.map(x => `<button class=\"btn${x===apvType?\" gold\":\"\"}\" data-at=\"${esc(x)}\" style=\"padding:6px 11px;font-size:12px\">${esc(x)}</button>`).join(\"\");\n  const pendingAll = DATA.approvals.filter(a => !decided[a.id]);\n  const pending = pendingAll.filter(a => apvType === \"All\" || a.type === apvType);\n  $(\"apvAll\").style.display = pending.length ? \"\" : \"none\";\n  $(\"apvCount\").textContent = pendingAll.length;\n  $(\"apvSub\").textContent = pendingAll.length ? pendingAll.length + \" of \" + DATA.approvals.length + \" items to review\" : \"Nothing waiting right now\";\n  if (!pending.length) {\n    $(\"apvQueue\").innerHTML = `<div class=\"empty\"><b>Nothing waiting for approval</b>${DATA.status === \"prelaunch\" ? \"The first content pack arrives here during the preparation phase, before anything is posted.\" : \"You're all caught up. New content appears here before it is scheduled.\"}</div>`;\n  } else {\n    $(\"apvQueue\").innerHTML = pending.map(a => `\n      <div class=\"apv\" id=\"apv-${esc(a.id)}\">\n        <div>${a.video ? `<button type=\"button\" class=\"vthumb\" data-video=\"${esc(a.video)}\" aria-label=\"Play video\"><img src=\"${esc(a.image || \"\")}\" alt=\"\" loading=\"lazy\"><span class=\"vplay\">&#9654;</span><span class=\"vhint\">Click to play</span></button>` : a.image ? `<img src=\"${esc(a.image)}\" alt=\"\" loading=\"lazy\">` : `<div class=\"empty\" style=\"padding:40px 10px\">${esc(a.type)}</div>`}</div>\n        <div>\n          <h4>${esc(a.title)}</h4>\n          <div class=\"meta\"><span class=\"st pend\">${esc(a.type)}</span><span class=\"st wait\">${esc(a.placement)}</span><span class=\"st ok\">${esc(a.schedule)}</span></div>\n          <div class=\"cap\">${esc(a.caption)}</div>\n          <textarea placeholder=\"What should we change?\"></textarea>\n          <div class=\"acts\">\n            <button class=\"btn ok\" data-a=\"approve\" data-id=\"${esc(a.id)}\">Approve</button>\n            <button class=\"btn chg\" data-a=\"changes\" data-id=\"${esc(a.id)}\">Request changes</button>\n          </div>\n        </div>\n      </div>`).join(\"\");\n  }\n  const hist = Object.entries(decided).sort((a,b) => b[1].at.localeCompare(a[1].at));\n  $(\"apvHistory\").innerHTML = hist.length ? `<div class=\"list\">${hist.map(([id, h]) => {\n    const item = DATA.approvals.find(a => a.id === id) || { title: id };\n    return `<div class=\"row\"><div><div class=\"t\">${esc(item.title)}</div><div class=\"d\">${new Date(h.at).toLocaleString()}${h.comment ? \" \u00b7 \" + esc(h.comment) : \"\"}</div></div><span class=\"st ${h.decision === \"approve\" ? \"ok\" : \"chg\"}\">${h.decision === \"approve\" ? \"Approved\" : \"Changes requested\"}</span></div>`;\n  }).join(\"\")}</div>` : `<div class=\"empty\"><b>No decisions yet</b>Approvals and change requests are listed here with their date and time.</div>`;\n}\ndocument.addEventListener(\"click\", e => { const f = e.target.closest(\"[data-at]\"); if (!f) return; apvType = f.dataset.at; renderApprovals(); });\n$(\"apvAll\").addEventListener(\"click\", async () => {\n  const items = DATA.approvals.filter(a => !decided[a.id] && (apvType === \"All\" || a.type === apvType));\n  if (!items.length || !confirm(\"Approve all \" + items.length + \" items shown?\")) return;\n  $(\"apvAll\").disabled = true;\n  try {\n    const r = await fetch(\"/api/blocktreasure-approval\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ id: \"bulk\", title: items.length + \" items approved together\", decision: \"approve\", comment: items.map(a => a.id + \" \" + a.title).join(\"\\n\") }) });\n    if (!r.ok) throw new Error(\"bad\");\n    const at = new Date().toISOString();\n    items.forEach(a => decided[a.id] = { decision: \"approve\", comment: \"\", at });\n    store.set(\"bt_approvals\", decided); toast(items.length + \" items approved. BVN has been notified.\");\n  } catch (err) { toast(\"Could not send. Please try again or message BVN on Telegram.\"); }\n  $(\"apvAll\").disabled = false; renderApprovals();\n});\ndocument.addEventListener(\"click\", async e => {\n  const b = e.target.closest(\"[data-a]\"); if (!b) return;\n  const id = b.dataset.id, box = $(\"apv-\" + id), ta = box.querySelector(\"textarea\");\n  if (b.dataset.a === \"changes\" && ta.style.display !== \"block\") { ta.style.display = \"block\"; ta.focus(); b.textContent = \"Send change request\"; return; }\n  const decision = b.dataset.a === \"approve\" ? \"approve\" : \"changes\";\n  const comment = ta.value.trim();\n  if (decision === \"changes\" && !comment) { toast(\"Please add a short note on what to change\"); return; }\n  box.querySelectorAll(\"button\").forEach(x => x.disabled = true);\n  const item = DATA.approvals.find(a => a.id === id);\n  try {\n    const r = await fetch(\"/api/blocktreasure-approval\", { method: \"POST\", headers: { \"content-type\": \"application/json\" }, body: JSON.stringify({ id, title: item && item.title, decision, comment }) });\n    if (!r.ok) throw new Error(\"bad\");\n    decided[id] = { decision, comment, at: new Date().toISOString() }; store.set(\"bt_approvals\", decided);\n    toast(decision === \"approve\" ? \"Approved. BVN has been notified.\" : \"Change request sent to BVN.\");\n    renderApprovals();\n  } catch (err) {\n    box.querySelectorAll(\"button\").forEach(x => x.disabled = false);\n    toast(\"Could not send. Please try again or message BVN on Telegram.\");\n  }\n});\nrenderApprovals();\n\n/* accounts */\n(function(){\n  const acc = DATA.accounts;\n  $(\"accCount\").textContent = acc.length;\n  $(\"aConn\").innerHTML = acc.length + ` <small style=\"font-size:14px;color:var(--ink3)\">/ ${t.pages}</small>`;\n  $(\"aAud\").textContent = fmt(acc.reduce((s,a)=>s+(a.audience||0),0));\n  const plats = [...new Set(acc.map(a=>a.platform))];\n  $(\"aPlat\").textContent = plats.length ? plats.length : \"3\";\n  if (DATA.sim) return;\n  const types = [\"All\",\"Gaming page\",\"Player group\",\"Meme page\"];\n  let cur = \"All\";\n  const stl = { live: [\"ok\",\"Live\"], briefed: [\"pend\",\"Briefed\"], paused: [\"chg\",\"Paused\"] };\n  function draw(){\n    $(\"accFilters\").innerHTML = types.map(x => `<button class=\"btn${x===cur?\" gold\":\"\"}\" data-f=\"${x}\" style=\"padding:6px 11px;font-size:12px\">${x}</button>`).join(\"\");\n    const rows = acc.filter(a => cur === \"All\" || a.type === cur).sort((a,b)=>(b.engagement||0)-(a.engagement||0));\n    $(\"accTable\").innerHTML = rows.length\n      ? `<div class=\"tablewrap\"><table><thead><tr><th>Account</th><th>Platform</th><th>Type</th><th>Audience</th><th>Posts</th><th>Reach</th><th>Engagement</th><th>Eng. rate</th><th>Status</th></tr></thead><tbody>${\n          rows.map(a => `<tr><td>${a.link ? `<a href=\"${esc(a.link)}\" target=\"_blank\" rel=\"noopener\" style=\"color:#F6D27E;text-decoration:none\">${esc(a.name)}</a>` : esc(a.name)}</td><td>${esc(a.platform)}</td><td>${esc(a.type)}</td><td>${fmt(a.audience)}</td><td>${a.posts||0}</td><td>${fmt(a.reach)}</td><td>${fmt(a.engagement)}</td><td>${a.reach ? (100*a.engagement/a.reach).toFixed(1)+\"%\" : \"0%\"}</td><td><span class=\"st ${(stl[a.status]||stl.briefed)[0]}\">${(stl[a.status]||stl.briefed)[1]}</span></td></tr>`).join(\"\")\n        }</tbody></table></div>`\n      : `<div class=\"empty\"><b>Accounts appear here once connected</b>Every page, group and account in the campaign is listed with its audience size, posts, reach, engagement and status, starting in the preparation phase.</div>`;\n  }\n  document.addEventListener(\"click\", e => { const f = e.target.closest(\"[data-f]\"); if (!f) return; cur = f.dataset.f; draw(); });\n  draw();\n})();\n\n/* reports */\nconst posts = DATA.posts;\n$(\"rEr\").textContent = er;\n$(\"rAvg\").textContent = posts.length ? fmt(Math.round(posts.reduce((s,p)=>s+(p.reach||0),0)/posts.length)) : \"0\";\nconst plannedToDate = DATA.sim ? d.posts : DATA.weeks.filter(w => w.delivered > 0).reduce((s,w)=>s+w.planned,0);\n$(\"rPace\").textContent = plannedToDate ? Math.round(100*d.posts/plannedToDate) + \"%\" : \"On track\";\n(function(){\n  const by = {};\n  posts.forEach(p => { by[p.type] = by[p.type] || { n:0, e:0 }; by[p.type].n++; by[p.type].e += p.engagement || 0; });\n  const rows = Object.entries(by).map(([k,v]) => [k, v.e/v.n]).sort((a,b)=>b[1]-a[1]);\n  const max = rows.length ? rows[0][1] : 1;\n  $(\"byType\").innerHTML = rows.length ? rows.map(([k,v]) => `<div style=\"margin:10px 0\"><div style=\"display:flex;justify-content:space-between;font-size:13px\"><span>${esc(k)}</span><b>${fmt(Math.round(v))}</b></div><div class=\"bar\"><i style=\"width:${100*v/max}%\"></i></div></div>`).join(\"\")\n    : `<div class=\"empty\"><b>Available after week 1</b>Gameplay clips, memes, polls and big win moments are compared here so budget moves to what works.</div>`;\n  const pg = {};\n  posts.forEach(p => { pg[p.page] = pg[p.page] || { type: p.pageType, n:0, r:0, e:0 }; pg[p.page].n++; pg[p.page].r += p.reach||0; pg[p.page].e += p.engagement||0; });\n  const top = Object.entries(pg).sort((a,b)=>b[1].e-a[1].e).slice(0,10);\n  $(\"topPages\").innerHTML = top.length ? `<div class=\"tablewrap\"><table><thead><tr><th>#</th><th>Page or group</th><th>Type</th><th>Posts</th><th>Reach</th><th>Engagement</th></tr></thead><tbody>${top.map(([k,v],i)=>`<tr><td class=\"mono\">${i+1}</td><td>${esc(k)}</td><td>${esc(v.type)}</td><td>${v.n}</td><td>${fmt(v.r)}</td><td>${fmt(v.e)}</td></tr>`).join(\"\")}</tbody></table></div>`\n    : `<div class=\"empty\"><b>Available after week 1</b>The top 10 pages and groups by engagement are ranked here every week.</div>`;\n})();\n$(\"reports\").innerHTML = DATA.reports.map(r => `<div class=\"row\"><div><div class=\"t\">${esc(r.title)}</div><div class=\"d\">${esc(r.desc)}</div></div>${r.url ? `<a class=\"btn\" href=\"${esc(r.url)}\" target=\"_blank\" rel=\"noopener\">Open</a>` : `<span class=\"st ${r.status}\">${r.status === \"ok\" ? \"Ready\" : \"Scheduled\"}</span>`}</div>`).join(\"\");\n$(\"btnPrint\").addEventListener(\"click\", () => {\n  document.querySelectorAll(\".view\").forEach(v => v.classList.toggle(\"printme\", v.id === \"v-overview\" || v.id === \"v-reports\"));\n  window.print();\n});\n$(\"btnCsv\").addEventListener(\"click\", () => {\n  if (!posts.length) { toast(\"The post log is empty until launch\"); return; }\n  const head = [\"Date\",\"Page\",\"Page type\",\"Content type\",\"Content\",\"Reach\",\"Engagement\",\"Comments\"];\n  const lines = [head].concat(posts.map(p => [p.date,p.page,p.pageType,p.type,p.title,p.reach,p.engagement,p.comments]))\n    .map(r => r.map(v => '\"' + String(v == null ? \"\" : v).replace(/\"/g,'\"\"') + '\"').join(\",\")).join(\"\\n\");\n  const a = document.createElement(\"a\"); a.href = URL.createObjectURL(new Blob([lines], { type: \"text/csv\" })); a.download = \"block-treasure-post-log.csv\"; a.click();\n});\n\n/* post log */\n$(\"log\").innerHTML = posts.length\n  ? `<div class=\"tablewrap\"><table><thead><tr><th>Date</th><th>Page or group</th><th>Type</th><th>Content</th><th>Reach</th><th>Engagement</th><th>Comments</th></tr></thead><tbody>${\n      posts.map(p => `<tr><td class=\"mono\">${esc(p.date)}</td><td>${esc(p.page)}</td><td>${esc(p.pageType)}</td><td>${esc(p.type)}${p.title ? `<div style=\"font-size:12px;color:var(--ink3)\">${esc(p.title)}</div>` : \"\"}</td><td>${fmt(p.reach)}</td><td>${fmt(p.engagement)}</td><td>${fmt(p.comments)}</td></tr>`).join(\"\")\n    }</tbody></table></div>`\n  : `<div class=\"empty\"><b>No posts yet</b>The first posts appear here on launch day, each with its page, link, reach, engagement and comments.</div>`;\n\n/* docs + payment */\n$(\"payStatus\").textContent = DATA.paid ? \"Paid\" : \"Awaiting payment\";\n$(\"payStatus\").className = \"st \" + (DATA.paid ? \"ok\" : \"wait\");\n$(\"docs\").innerHTML = DATA.docs.map(x => `<div class=\"row\"><div><div class=\"t\">${esc(x.title)}</div><div class=\"d\">${esc(x.desc)}</div></div><a class=\"btn\" href=\"${esc(x.url)}\" target=\"_blank\" rel=\"noopener\">Open PDF</a></div>`).join(\"\");\n$(\"btnCopy\").addEventListener(\"click\", async () => {\n  const w = $(\"wallet\").textContent.trim();\n  try { await navigator.clipboard.writeText(w); toast(\"Wallet address copied\"); }\n  catch (e) { const r = document.createRange(); r.selectNodeContents($(\"wallet\")); const s = getSelection(); s.removeAllRanges(); s.addRange(r); toast(\"Address selected, press copy\"); }\n});\n\n/* detailed accounts and reports */\n(function(){\n  if (!DATA.sim) return;\n  const now = Date.now();\n  const S = DATA.sim.snapshot(now);\n  const P = S.posts;\n  const acc = DATA.accounts;\n  const rate = (e, r) => r ? (100 * e / r).toFixed(1) + \"%\" : \"0%\";\n  const sum = (a, k) => a.reduce((s, x) => s + (x[k] || 0), 0);\n  const table = (head, rows) => `<div class=\"tablewrap\"><table><thead><tr>${head.map(h => `<th>${h}</th>`).join(\"\")}</tr></thead><tbody>${rows.join(\"\")}</tbody></table></div>`;\n  const MON = [\"Jan\",\"Feb\",\"Mar\",\"Apr\",\"May\",\"Jun\",\"Jul\",\"Aug\",\"Sep\",\"Oct\",\"Nov\",\"Dec\"];\n  const dstr = ms => { const d = new Date(ms + 8 * 36e5); return d.getUTCDate() + \" \" + MON[d.getUTCMonth()]; };\n  const perPage = {};\n  P.forEach(p => { (perPage[p.page] = perPage[p.page] || []).push(p); });\n\n  /* ---------- accounts: by page type ---------- */\n  const groups = [[\"Gaming page\", \"Gaming pages\"], [\"Player group\", \"Player groups\"], [\"Meme page\", \"Meme and entertainment pages\"]];\n  $(\"accTypes\").innerHTML = groups.map(([k, label]) => {\n    const a = acc.filter(x => x.type === k), ps = P.filter(p => p.pageType === k);\n    const r = sum(ps, \"reach\"), e = sum(ps, \"engagement\");\n    return `<div class=\"card kpi\"><div class=\"lbl\">${label}</div><div class=\"val\">${fmt(r)} <small>reach</small></div>\n      <div class=\"sub\">${a.filter(x => x.status === \"live\").length} of ${a.length} accounts live \u00b7 ${fmt(sum(a, \"audience\"))} audience</div>\n      <div class=\"mini\"><div><b>${ps.length}</b><span>posts</span></div><div><b>${fmt(e)}</b><span>engagement</span></div><div><b>${rate(e, r)}</b><span>eng. rate</span></div><div><b>${fmt(sum(ps, \"comments\"))}</b><span>comments</span></div></div></div>`;\n  }).join(\"\");\n\n  /* ---------- accounts: platforms ---------- */\n  const plats = [...new Set(acc.map(a => a.platform))];\n  $(\"accPlat\").innerHTML = table([\"Platform\", \"Accounts\", \"Audience\", \"Posts\", \"Reach\", \"Engagement\", \"Eng. rate\", \"Comments\"], plats.map(pl => {\n    const a = acc.filter(x => x.platform === pl), names = new Set(a.map(x => x.name)), ps = P.filter(p => names.has(p.page));\n    const r = sum(ps, \"reach\"), e = sum(ps, \"engagement\");\n    return `<tr><td>${esc(pl)}</td><td>${a.length}</td><td>${fmt(sum(a, \"audience\"))}</td><td>${ps.length}</td><td>${fmt(r)}</td><td>${fmt(e)}</td><td>${rate(e, r)}</td><td>${fmt(sum(ps, \"comments\"))}</td></tr>`;\n  }));\n\n  /* ---------- accounts: network table with details ---------- */\n  const types = [\"All\", \"Gaming page\", \"Player group\", \"Meme page\"];\n  let cur = \"All\", open = null;\n  const stl = { live: [\"ok\", \"Live\"], briefed: [\"pend\", \"Briefed\"], paused: [\"chg\", \"Paused\"] };\n  function detail(a) {\n    const ps = (perPage[a.name] || []).slice().sort((x, y) => y.at - x.at);\n    const nxt = DATA.sim.sched.find(p => p.pg.name === a.name && p.t > now);\n    const r = sum(ps, \"reach\"), e = sum(ps, \"engagement\");\n    const best = ps.slice().sort((x, y) => y.engagement - x.engagement)[0];\n    const head = `<div class=\"tgrid\" style=\"margin-bottom:12px\">\n      <div class=\"tv\"><b>${fmt(a.audience)}</b><span>${a.type === \"Player group\" ? \"members\" : \"followers\"}</span></div>\n      <div class=\"tv\"><b>${ps.length}</b><span>posts so far</span></div>\n      <div class=\"tv\"><b>${ps.length ? fmt(Math.round(r / ps.length)) : 0}</b><span>avg reach per post</span></div>\n      <div class=\"tv\"><b>${rate(e, r)}</b><span>engagement rate</span></div></div>\n      <div class=\"d\" style=\"margin-bottom:10px\">${best ? `Best post: <b>${esc(best.title)}</b> (${esc(best.type)}), ${fmt(best.engagement)} engagement. ` : \"\"}${nxt ? `Next post: ${esc(nxt.a.title)}, ${DATA.sim.stamp(nxt.t)}.` : \"No more posts scheduled for this account.\"}</div>`;\n    return head + (ps.length ? table([\"Date\", \"Content\", \"Type\", \"Reach\", \"Engagement\", \"Comments\"], ps.map(p => `<tr><td class=\"mono\">${esc(p.date)}</td><td>${esc(p.title)}</td><td>${esc(p.type)}</td><td>${fmt(p.reach)}</td><td>${fmt(p.engagement)}</td><td>${fmt(p.comments)}</td></tr>`))\n      : `<div class=\"empty\"><b>Briefed and ready</b>${nxt ? \"First post goes out \" + DATA.sim.stamp(nxt.t) + \".\" : \"\"}</div>`);\n  }\n  function draw() {\n    $(\"accFilters\").innerHTML = types.map(x => `<button class=\"btn${x === cur ? \" gold\" : \"\"}\" data-f=\"${x}\" style=\"padding:6px 11px;font-size:12px\">${x}</button>`).join(\"\");\n    const rows = acc.filter(a => cur === \"All\" || a.type === cur).sort((a, b) => (b.engagement || 0) - (a.engagement || 0));\n    $(\"accTable\").innerHTML = `<div class=\"d\" style=\"margin-bottom:10px;color:var(--ink3);font-size:12.5px\">Click an account to see every post it has made.</div>` + table(\n      [\"Account\", \"Platform\", \"Type\", \"Audience\", \"Posts\", \"Reach\", \"Avg reach\", \"Engagement\", \"Eng. rate\", \"Comments\", \"Last post\", \"Status\"],\n      rows.map(a => {\n        const ps = perPage[a.name] || [], last = ps.length ? ps[ps.length - 1] : null, s = stl[a.status] || stl.briefed;\n        return `<tr class=\"accrow${open === a.name ? \" on\" : \"\"}\" data-acc=\"${esc(a.name)}\"><td><span class=\"caret\">${open === a.name ? \"\u25be\" : \"\u25b8\"}</span> ${esc(a.name)}</td><td>${esc(a.platform)}</td><td>${esc(a.type)}</td><td>${fmt(a.audience)}</td><td>${a.posts || 0}</td><td>${fmt(a.reach)}</td><td>${a.posts ? fmt(Math.round(a.reach / a.posts)) : \"0\"}</td><td>${fmt(a.engagement)}</td><td>${rate(a.engagement, a.reach)}</td><td>${fmt(sum(ps, \"comments\"))}</td><td class=\"mono\">${last ? esc(last.date) : \"Not yet\"}</td><td><span class=\"st ${s[0]}\">${s[1]}</span></td></tr>` +\n          (open === a.name ? `<tr class=\"accd\"><td colspan=\"12\">${detail(a)}</td></tr>` : \"\");\n      }));\n  }\n  document.addEventListener(\"click\", e => {\n    const f = e.target.closest(\"[data-f]\"); if (f) { cur = f.dataset.f; draw(); return; }\n    const r = e.target.closest(\"[data-acc]\"); if (r) { open = open === r.dataset.acc ? null : r.dataset.acc; draw(); }\n  });\n  draw();\n\n  /* ---------- reports: week by week ---------- */\n  const W = DATA.weeks.map((w, i) => {\n    const ps = P.filter(p => p.week === i), r = sum(ps, \"reach\"), e = sum(ps, \"engagement\");\n    const a = DATA.sim.START + i * 7 * 864e5, b = a + 6 * 864e5;\n    const started = now >= a, ended = now >= b + 864e5;\n    return { i, label: w.label, dates: dstr(a) + \" to \" + dstr(b), planned: w.planned, ps, r, e, c: sum(ps, \"comments\"), started, ended };\n  });\n  $(\"rWeeks\").innerHTML = table([\"Week\", \"Dates\", \"Posts\", \"Reach\", \"Engagement\", \"Eng. rate\", \"Comments\", \"Status\"], W.map(w =>\n    `<tr><td>${w.label}</td><td>${w.dates}</td><td>${w.ps.length} <span style=\"color:var(--ink3)\">/ ${w.planned}</span></td><td>${fmt(w.r)}</td><td>${fmt(w.e)}</td><td>${rate(w.e, w.r)}</td><td>${fmt(w.c)}</td><td><span class=\"st ${w.ended ? \"ok\" : w.started ? \"pend\" : \"wait\"}\">${w.ended ? \"Complete\" : w.started ? \"In progress\" : \"Scheduled\"}</span></td></tr>`));\n\n  /* ---------- reports: content types, platforms, page types ---------- */\n  const groupBy = (key) => { const m = {}; P.forEach(p => { const k = p[key]; m[k] = m[k] || []; m[k].push(p); }); return Object.entries(m).map(([k, ps]) => ({ k, ps, r: sum(ps, \"reach\"), e: sum(ps, \"engagement\"), c: sum(ps, \"comments\") })).sort((a, b) => b.e / b.ps.length - a.e / a.ps.length); };\n  const noData = `<div class=\"empty\"><b>Fills in as posts go live</b>Numbers appear here from the first post.</div>`;\n  const ct = groupBy(\"type\");\n  $(\"rTypes\").innerHTML = ct.length ? table([\"Content type\", \"Posts\", \"Reach\", \"Avg reach\", \"Avg engagement\", \"Eng. rate\", \"Comments\"], ct.map(g =>\n    `<tr><td>${esc(g.k)}</td><td>${g.ps.length}</td><td>${fmt(g.r)}</td><td>${fmt(Math.round(g.r / g.ps.length))}</td><td>${fmt(Math.round(g.e / g.ps.length))}</td><td>${rate(g.e, g.r)}</td><td>${fmt(g.c)}</td></tr>`)) : noData;\n  P.forEach(p => { p.platform = p.pgRef.platform; });\n  const pl = groupBy(\"platform\").sort((a, b) => b.r - a.r);\n  $(\"rPlat\").innerHTML = pl.length ? table([\"Platform\", \"Posts\", \"Reach\", \"Share of reach\", \"Eng. rate\", \"Comments\"], pl.map(g =>\n    `<tr><td>${esc(g.k)}</td><td>${g.ps.length}</td><td>${fmt(g.r)}</td><td>${S.reach ? Math.round(100 * g.r / S.reach) : 0}%</td><td>${rate(g.e, g.r)}</td><td>${fmt(g.c)}</td></tr>`)) : noData;\n  const pt = groupBy(\"pageType\");\n  $(\"rPageTypes\").innerHTML = pt.length ? table([\"Page type\", \"Posts\", \"Avg reach\", \"Avg engagement\", \"Avg comments\", \"Eng. rate\"], pt.map(g =>\n    `<tr><td>${esc(g.k)}</td><td>${g.ps.length}</td><td>${fmt(Math.round(g.r / g.ps.length))}</td><td>${fmt(Math.round(g.e / g.ps.length))}</td><td>${fmt(Math.round(g.c / g.ps.length))}</td><td>${rate(g.e, g.r)}</td></tr>`)) : noData;\n\n  /* ---------- reports: best time to post ---------- */\n  const buckets = [[\"7 AM\", 7, 10], [\"10 AM\", 10, 13], [\"1 PM\", 13, 16], [\"4 PM\", 16, 19], [\"7 PM\", 19, 22], [\"10 PM\", 22, 27]];\n  const hrOf = p => { const h = new Date(p.at + 8 * 36e5).getUTCHours(); return h < 3 ? h + 24 : h; };\n  const hv = buckets.map(([, a, b]) => { const ps = P.filter(p => { const h = hrOf(p); return h >= a && h < b; }); const r = sum(ps, \"reach\"); return r ? Math.round(1000 * sum(ps, \"engagement\") / r) / 10 : 0; });\n  barChart(\"chartHours\", [hv], buckets.map(b => b[0]), [\"#5B8CFF\"], v => v + \"%\");\n\n  /* ---------- reports: top 10 posts ---------- */\n  const top = P.slice().sort((a, b) => b.engagement - a.engagement).slice(0, 10);\n  $(\"rTopPosts\").innerHTML = top.length ? table([\"#\", \"Date\", \"Content\", \"Type\", \"Page or group\", \"Reach\", \"Engagement\", \"Comments\"], top.map((p, i) =>\n    `<tr><td class=\"mono\">${i + 1}</td><td class=\"mono\">${esc(p.date)}</td><td>${esc(p.title)}</td><td>${esc(p.type)}</td><td>${esc(p.page)}</td><td>${fmt(p.reach)}</td><td>${fmt(p.engagement)}</td><td>${fmt(p.comments)}</td></tr>`)) : noData;\n\n  /* ---------- reports: weekly reports you can open ---------- */\n  function weekReport(ps, label, last) {\n    if (!ps.length) return `<div class=\"empty\"><b>No posts yet</b>This report fills in once the first posts of the week go live.</div>`;\n    const r = sum(ps, \"reach\"), e = sum(ps, \"engagement\"), c = sum(ps, \"comments\");\n    const tp = ps.slice().sort((a, b) => b.engagement - a.engagement).slice(0, 3);\n    const pg = {}; ps.forEach(p => { pg[p.page] = pg[p.page] || { e: 0, n: 0, t: p.pageType }; pg[p.page].e += p.engagement; pg[p.page].n++; });\n    const tpg = Object.entries(pg).sort((a, b) => b[1].e - a[1].e).slice(0, 3);\n    const ty = {}; ps.forEach(p => { ty[p.type] = ty[p.type] || { e: 0, n: 0 }; ty[p.type].e += p.engagement; ty[p.type].n++; });\n    const bt = Object.entries(ty).sort((a, b) => b[1].e / b[1].n - a[1].e / a[1].n)[0];\n    const next = last\n      ? `Keep ${bt[0].toLowerCase()} posts on the top 10 pages and groups, and add more ${tpg[0][1].t.toLowerCase()} placements like ${tpg[0][0]}.`\n      : `More posts move to ${bt[0].toLowerCase()} content and to the strongest accounts, starting with ${tpg.map(x => x[0]).slice(0, 2).join(\" and \")}.`;\n    return `<div class=\"wrep\">\n      <div class=\"tgrid\"><div class=\"tv\"><b>${ps.length}</b><span>posts</span></div><div class=\"tv\"><b>${fmt(r)}</b><span>reach</span></div><div class=\"tv\"><b>${fmt(e)}</b><span>engagement, ${rate(e, r)}</span></div><div class=\"tv\"><b>${fmt(c)}</b><span>comments</span></div></div>\n      <div class=\"g2\" style=\"margin-top:14px;gap:14px\">\n        <div><h4>Top posts</h4>${tp.map((p, i) => `<div class=\"feedrow\"><div><div class=\"t\">${i + 1}. ${esc(p.title)}</div><div class=\"d\">${esc(p.page)} \u00b7 ${esc(p.type)} \u00b7 ${esc(p.date)}</div></div><div class=\"n\"><b>${fmt(p.engagement)}</b><small>engagement</small></div></div>`).join(\"\")}</div>\n        <div><h4>Top pages and groups</h4>${tpg.map(([k, v], i) => `<div class=\"feedrow\"><div><div class=\"t\">${i + 1}. ${esc(k)}</div><div class=\"d\">${esc(v.t)} \u00b7 ${v.n} post${v.n > 1 ? \"s\" : \"\"}</div></div><div class=\"n\"><b>${fmt(v.e)}</b><small>engagement</small></div></div>`).join(\"\")}</div>\n      </div>\n      <p style=\"margin:14px 0 4px\"><b>Best format:</b> ${esc(bt[0])}, averaging ${fmt(Math.round(bt[1].e / bt[1].n))} engagement per post.</p>\n      <p style=\"margin:0\"><b>${last ? \"Recommendation\" : \"Next week\"}:</b> ${esc(next)}</p>\n    </div>`;\n  }\n  let openRep = null;\n  function drawReports() {\n    $(\"reports\").innerHTML = DATA.reports.map((r, i) => {\n      const last = i === DATA.reports.length - 1;\n      const w = W[Math.min(i, W.length - 1)];\n      const ready = r.status === \"ok\", live = !ready && w.started;\n      const ps = last ? P : w.ps;\n      return `<div class=\"row\" style=\"flex-wrap:wrap\"><div><div class=\"t\">${esc(r.title)}</div><div class=\"d\">${esc(r.desc)} \u00b7 ${last ? dstr(DATA.sim.START) + \" to \" + dstr(DATA.sim.START + 27 * 864e5) : w.dates}</div></div>\n        ${ready || live ? `<button class=\"btn${ready ? \" gold\" : \"\"}\" data-rep=\"${i}\">${openRep === i ? \"Hide\" : ready ? \"View report\" : \"View so far\"}</button>` : `<span class=\"st pend\">Scheduled</span>`}\n        ${openRep === i ? `<div style=\"flex-basis:100%;margin-top:12px\">${weekReport(ps, r.title, last)}</div>` : \"\"}</div>`;\n    }).join(\"\");\n  }\n  document.addEventListener(\"click\", e => { const b = e.target.closest(\"[data-rep]\"); if (!b) return; const i = +b.dataset.rep; openRep = openRep === i ? null : i; drawReports(); });\n  drawReports();\n})();\n\n/* live overview: today, daily reach, latest posts */\n(function(){\n  if (!DATA.sim) return;\n  $(\"liveWrap\").style.display = \"\";\n  const ago = ms => { const m = Math.max(1, Math.round((Date.now() - ms) / 6e4)); return m < 60 ? m + \" min ago\" : m < 1440 ? Math.round(m / 60) + \" hr ago\" : Math.round(m / 1440) + \" d ago\"; };\n  function draw() {\n    const now = Date.now(), T = DATA.sim.today(now);\n    $(\"todayDate\").textContent = DATA.sim.done ? \"Campaign complete\" : DATA.sim.stamp(now);\n    $(\"today\").innerHTML = [[\"Posts today\", T.posts], [\"Reach today\", fmt(T.reach)], [\"Engagement today\", fmt(T.eng)], [\"New comments\", fmt(T.comments)]]\n      .map(([k, v]) => `<div class=\"tv\"><b>${v}</b><span>${k}</span></div>`).join(\"\");\n    const daily = DATA.sim.daily(now);\n    barChart(\"chartDaily\", [daily], daily.map((_, i) => { const d = new Date(DATA.sim.START + 8 * 36e5 + i * 864e5); return i % 3 === 0 ? String(d.getUTCDate()) : \"\"; }), [\"#E8B54A\"], fmt);\n    const S = DATA.sim.snapshot(now);\n    $(\"feed\").innerHTML = S.posts.length ? S.posts.slice(-7).reverse().map(p => `<div class=\"feedrow\"><div><div class=\"t\">${esc(p.title)}</div><div class=\"d\">${esc(p.page)} \u00b7 ${esc(p.type)} \u00b7 ${ago(p.at)}</div></div><div class=\"n\"><b>${fmt(p.reach)}</b><small>reach</small></div></div>`).join(\"\")\n      : `<div class=\"empty\"><b>First posts go out this morning</b>Each post appears here as soon as it is live.</div>`;\n    if ($(\"cdToday\")) $(\"cdToday\").textContent = T.posts;\n    $(\"updated\").textContent = DATA.sim.stamp(now);\n  }\n  draw();\n  setInterval(draw, 60000);\n})();\n\n(function(){\n  const box = document.createElement(\"div\");\n  box.className = \"vbox\";\n  box.innerHTML = '<button type=\"button\" class=\"vclose\">Close</button><video controls playsinline></video>';\n  document.body.appendChild(box);\n  const vid = box.querySelector(\"video\");\n  function closeBox(){ vid.pause(); vid.removeAttribute(\"src\"); vid.load(); box.classList.remove(\"on\"); }\n  document.addEventListener(\"click\", e => {\n    const t = e.target.closest && e.target.closest(\".vthumb\");\n    if (t) {\n      e.preventDefault();\n      vid.src = t.dataset.video;\n      box.classList.add(\"on\");\n      vid.play().catch(() => {});\n      return;\n    }\n    if (box.classList.contains(\"on\") && (e.target === box || e.target.closest(\".vclose\"))) closeBox();\n  });\n  document.addEventListener(\"keydown\", e => { if (e.key === \"Escape\" && box.classList.contains(\"on\")) closeBox(); });\n})();\n</script>\n</body>\n</html>\n";
